      "type": "object",
      "description": "Move the booking to this apartment and room.",
      "properties": {
        "apartment": {
          "type": "string"
        },
        "room": {
          "type": "string",
          "description": "The room number, digits only."
        }
      },
      "required": [
        "apartment",
        "room"
      ]
    },
    "stay": {
      "type": "object",
      "description": "Change how long the guest stays.",
      "properties": {
        "kind": {
          "type": "string",
          "enum": [
            "extend",
            "until",
            "leave"
          ]
        },
        "nights": {
          "type": "integer",
          "description": "For kind=extend: how many nights to add."
        },
        "date": {
          "type": "string",
          "description": "yyyy-mm-dd. For kind=until: the last day. For kind=leave: the day the guest left; leave it out for today."
        }
      },
      "required": [
        "kind"
      ]
    },
    "unclear": {
      "type": "string",
      "description": "Only when the request cannot be understood: a short reason, in the staff member's language."
    }
  }
}

parameters.jsCode:
/**
 * Turns the Brain's named save.fields into one flat row for the Google Sheets
 * `update` node, and works out which row to write.
 *
 * The row comes from the Sheets API's own `values` array — A1:J2000, read by
 * "Read Booking Key". Its length IS the last occupied row: the API trims
 * trailing empty rows, keeps interior blanks as empty arrays, and counts from
 * row 1. So the next free row is one below it, and nothing here has to guess
 * what n8n considered a header or how it numbered what it returned.
 *
 * Both earlier attempts got that wrong in the same place. Counting the items a
 * Sheets node returned wrote an expense over a hand-typed row on 2026-08-14 —
 * that row's key column was empty, so the count never saw it. Taking
 * max(row_number) + 1 instead was one short, because the node numbers rows from
 * its own view of the range and not the sheet's: it wrote over the last row of
 * both tabs, reported 2026-08-15.
 *
 * The range stops at J deliberately. K, N, P, R, S and T carry fill-down
 * formulas that evaluate to '' far below the data, and a row answering '' would
 * count as occupied — every write would land at the bottom of the sheet.
 */

const save = $('Brain').first().json.save;

/** The first free row, from whichever shape the read produced. */
function nextRow() {
  const items = $input.all();
  const head = items.length ? items[0].json : null;

  // The Sheets API response. `values` is absent entirely on an empty tab.
  if (head && Object.prototype.hasOwnProperty.call(head, 'range')) {
    return (Array.isArray(head.values) ? head.values.length : 0) + 1;
  }

  // Fallback: a Sheets node's items, one per row. Only reachable if the read is
  // swapped back; kept so a half-applied deploy appends below the data rather
  // than into the middle of it.
  const rows = items.filter((i) => {
    if (!i.json) return false;
    return Object.keys(i.json).some(
      (k) => k !== 'row_number' && i.json[k] !== '' && i.json[k] != null,
    );
  });
  const numbered = rows
    .map((i) => Number(i.json.row_number))
    .filter((n) => Number.isFinite(n));
  return numbered.length ? Math.max(...numbered) + 1 : rows.length + 2;
}

const r = nextRow();

// The sheet's own calculated columns. Never written, on any path: a value —
// even '' — replaces the formula with a dead number, and the Dashboard and the
// per-property tabs all read them. A hard filter, not a convention.
const FORMULA_COLS = [
  'تاريخ المغادرة',   // K = J + I
  'نسبة البرنامج',    // N
  'المتبقي',          // P = L - M
  'تاريخ الإدخال',    // R
  'صافي الدخل',       // S = L - N
  'آخر تعديل',        // T
];

const out = { row_number: r };
for (const k of Object.keys(save.fields)) {
  if (FORMULA_COLS.indexOf(k) !== -1) continue;
  const v = save.fields[k];
  // e.g. the open-ended nights cell '=TODAY()-J{r}'
  out[k] = typeof v === 'string' ? v.replace(/\{r\}/g, String(r)) : v;
}

/**
 * P المتبقي — the sheet's own FORMULA, written by us. Never a number.
 *
 * P is still off-limits to `save.fields` (the filter above), and for the same
 * reason as ever: a computed value written into P is dead the moment the next
 * payment lands, and the Dashboard and every per-property tab read P expecting
 * it to track L − M.
 *
 * What changed is who puts the formula there. It used to be the sheet's own
 * fill-down, and a fill-down only reaches as far as somebody once dragged it —
 * measured 2026-09-21, it stops at row 89 while the last booking is on row 88.
 * The very next booking is fine and the one after it gets a permanently blank
 * P, which is the "rows whose calculated columns are empty" that
 * `supabase/heal_formulas.py` exists to repair after the fact.
 *
 * So the row carries its own formula down with it. The text is the sheet's,
 * copied off a healthy row, not an invention: the IF(C…) guard is what keeps a
 * half-written row from showing a stray 0, and the IFERROR keeps a non-numeric
 * L (a mixed-currency note, say) from spreading #VALUE! across the tab.
 *
 * N نسبة البرنامج, S صافي الدخل, R تاريخ الإدخال and T آخر تعديل still depend on
 * the fill-down and still need `heal_formulas.py`. Only P was asked for; each of
 * the others has a different pattern and one of them (N) branches on نوع الحجز.
 */
out['المتبقي'] = '=IF(C{r}="","",IFERROR(L{r}-M{r},""))'.replace(/\{r\}/g, String(r));

return [{ json: out }];

/**
 * Same as Build Booking Row, for the expense tab: A1:H2000, every column of it
 * hand-typed, so any cell in a row makes that row occupied.
 *
 * The row is `values.length + 1` — the Sheets API counts from row 1 and trims
 * only the empty tail, so its length is the last occupied row whatever state
 * the tab is in. See build_booking_row.js for the two ways this was got wrong
 * before, both of which wrote on top of somebody's data.
 */

const save = $('Brain').first().json.save;

function nextRow() {
  const items = $input.all();
  const head = items.length ? items[0].json : null;

  if (head && Object.prototype.hasOwnProperty.call(head, 'range')) {
    return (Array.isArray(head.values) ? head.values.length : 0) + 1;
  }

  const rows = items.filter((i) => {
    if (!i.json) return false;
    return Object.keys(i.json).some(
      (k) => k !== 'row_number' && i.json[k] !== '' && i.json[k] != null,
    );
  });
  const numbered = rows
    .map((i) => Number(i.json.row_number))
    .filter((n) => Number.isFinite(n));
  return numbered.length ? Math.max(...numbered) + 1 : rows.length + 2;
}

const r = nextRow();

const out = { row_number: r };
for (const k of Object.keys(save.fields)) {
  const v = save.fields[k];
  out[k] = typeof v === 'string' ? v.replace(/\{r\}/g, String(r)) : v;
}

return [{ json: out }];

/**
 * Flattens an edit/cancel save into one item for the Google Sheets `update` node.
 *
 * Unlike the append path there is no row arithmetic here — the row came from the
 * lookup. Only the columns the user actually changed are emitted, and the write
 * node uses autoMapInputData, so every other column (including the formula
 * columns K, N, P, R, S, T) is left untouched. Writing an unchanged value back
 * would be wrong for عدد الليالي in particular: the sheet may hold a live
 * =TODAY()-J{row} formula there and reading it back gives only its result.
 */

const save = $('Brain').first().json.save;

// The sheet's own calculated columns. Nothing this bot writes may ever name
// one: writing a value — even '' — replaces the formula with a dead number, and
// the Dashboard and every per-property tab read them.
//
// This is a hard filter rather than a convention. The Brain is careful today,
// but "careful" is what every one of these columns had before it was found
// empty, and a guard costs one line where an audit costs an afternoon.
const FORMULA_COLS = [
  'تاريخ المغادرة',   // K = J + I
  'نسبة البرنامج',    // N
  'المتبقي',          // P = L - M
  'تاريخ الإدخال',    // R
  'صافي الدخل',       // S = L - N
  'آخر تعديل',        // T
];

/** One row's changed columns, with the sheet's own kept out of reach. */
function rowItem(rowNumber, raw) {
  const fields = {};
  for (const k of Object.keys(raw || {})) {
    if (FORMULA_COLS.indexOf(k) !== -1) continue;
    fields[k] = raw[k];
  }
  return { json: { row_number: rowNumber, ...fields } };
}

const items = [rowItem(save.row, save.fields)];

// A cancellation covers every row the booking occupies, not just its own — see
// `lineRows` in brain.js. Nothing else emits them, so an ordinary edit is one
// item exactly as before.
for (const line of save.lineRows || []) {
  if (Number(line.row) > 0) items.push(rowItem(Number(line.row), line.fields));
}

return items;

/**
 * The `payment_line` flow: a payment in a method the booking's own row does not
 * carry. Emits the body of ONE Google Sheets `values:batchUpdate` call.
 *
 * Up to two rows are written, and both are updates — nothing here appends:
 *
 *   1. the LINE. Either a row this branch has just inserted under the booking's
 *      block, or one that already carries this method and whose paid cell
 *      simply grows.
 *   2. the BOOKING's own row, when something on it changed in the same session.
 *      Absent when nothing did. Its اجمالي سعر الحجز is NOT among the changes —
 *      the agreed price stays whole there and the line leaves that cell blank.
 *
 * ## Why this builds a request body instead of rows
 *
 * It used to emit one item per row for a `googleSheets` update node. Measured
 * live on 2026-08-20, execution 1937: that node took **32,618 ms** of a 36,870 ms
 * turn — 88% of it — while every other node in the same execution finished
 * inside 450 ms. The receptionist watched a spinner for 37 seconds and tapped
 * Save again during the wait.
 *
 * The node has to FIND each row before it can write it: it reads the tab,
 * matching on `row_number`, and that read makes Google recalculate a workbook
 * carrying GOOGLEFINANCE calls and per-apartment FILTER(UNIQUE(…)) over
 * unbounded ranges. The same execution wrote column U through a plain HTTP node
 * in 287 ms. Nothing needs finding here — the row number is known and so is
 * every column — so this addresses the cells outright, exactly as
 * `values_put_id` does, and the whole write becomes one request.
 *
 * ## One range per field, deliberately
 *
 * Not one range per row. A row's changed fields are not contiguous — the
 * booking's own row often changes عدد الليالي and nothing else — and a
 * contiguous block write would blank every cell between the ones it meant to
 * set. A per-field range also means a column that is not named here is not
 * touched at all, which is what keeps K, N, P, R, S and T safe: they are sheet
 * formulas, and writing one — even an empty string — destroys it. They have no
 * entry in COLUMN below, so no range can ever address them.
 *
 * معرف النظام is likewise absent: "Write Line Id" writes column U afterwards in
 * its own request, for the same reason this node exists at all.
 */

const save = $('Brain').first().json.save;

/**
 * Header name -> column letter, for إدخال الحجوزات.
 *
 * The formula columns are missing on purpose and must stay missing:
 *   K تاريخ المغادرة   N نسبة البرنامج   P المتبقي
 *   R تاريخ الإدخال    S صافي الدخل      T آخر تعديل
 * E الجنسية is retired and left exactly as found. U is written elsewhere.
 */
const COLUMN = {
  'بوكنج ID': 'A',
  'ID': 'B',
  'اسم المقيم': 'C',
  'نوع الحجز': 'D',
  'رقم الهاتف': 'F',
  'اسم الشقة': 'G',
  'رقم الغرفة': 'H',
  'عدد الليالي': 'I',
  'تاريخ البداية': 'J',
  'اجمالي سعر الحجز': 'L',
  'اجمالي ما تم دفعه': 'M',
  'طريقة الدفع': 'O',
  'ملاحظات': 'Q',
};

const TAB = $('Config').first().json.BOOKINGS_TAB;
const data = [];

/** Add one field of one row, if it is a column this bot owns. */
function put(row, header, value) {
  const col = COLUMN[header];
  if (!col) return;                    // a formula column, or one we do not write
  // '=TODAY()-J{r}' on an open-ended stay: the row counts its own nights from
  // its OWN row, so {r} is this row and never the booking's.
  const v = typeof value === 'string' ? value.replace(/\{r\}/g, String(row)) : value;
  data.push({
    range: `'${TAB.replace(/'/g, "''")}'!${col}${row}`,
    values: [[v === undefined || v === null ? '' : v]],
  });
}

for (const header of Object.keys(save.fields || {})) {
  put(save.row, header, save.fields[header]);
}

if (save.bookingFields && Object.keys(save.bookingFields).length) {
  for (const header of Object.keys(save.bookingFields)) {
    put(save.bookingRow, header, save.bookingFields[header]);
  }
}

// One item, one request. Downstream nodes that only care that the write
// happened — Has Group?, Write Line Id — no longer see an item per row, which
// is what used to make them run twice.
return [{ json: { data, rows: data.length ? 1 : 0 } }];
